std::uint64_t test_millis(){return static_cast<std::uint64_t>(std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now().time_since_epoch()).count());}
std::size_t held_directory(const std::filesystem::path& path){std::size_t found{};for(const auto& entry:std::filesystem::directory_iterator("/proc/self/fd")){std::error_code error;const auto target=std::filesystem::read_symlink(entry.path(),error);if(!error&&target==path)++found;}return found;}
app::FileManagementJobStatus viewed(native::LinuxFileAdministration& service,const app::FileManagementTask& task){
    auto result=service.start(task);const auto deadline=test_millis()+15000;
    while(result.code==app::LocalAccountResultCode::ok&&result.state==app::FileManagementJobState::running&&test_millis()<deadline){std::this_thread::sleep_for(std::chrono::milliseconds(2));result=service.status(task.job);}
    check(result.code==app::LocalAccountResultCode::ok&&result.state!=app::FileManagementJobState::running,"preview worker finishes within native fixture deadline");check(app::valid_file_management_status(result)&&app::decode_file_management_status(app::encode_file_management_status(result)).has_value(),"actual native viewport survives bounded strict codec");return result;
}
std::string view_zip(){
    struct Free{void operator()(struct archive* p)const{archive_write_free(p);}};std::unique_ptr<struct archive,Free> writer(archive_write_new());std::string bytes;
    check(archive_write_set_format_zip(writer.get())==ARCHIVE_OK&&archive_write_set_bytes_per_block(writer.get(),0)==ARCHIVE_OK&&archive_write_open(writer.get(),&bytes,nullptr,zip_write,nullptr)==ARCHIVE_OK,"native ZIP source fixture begins");
    for(unsigned n=0;n<25;++n){const auto name=n==0?std::string("readme.txt"):n==1?std::string("art.ans"):n==2?std::string("binary.exe"):"inner/member-"+std::to_string(n)+".txt";const auto body=n==0?std::string("ZIP @FILEAREA@ text\n"):n==1?std::string("\x1b[1;32mGREEN\x1b[0m"):n==2?std::string("MZ\0binary",9):"Entry "+std::to_string(n);
        auto* entry=archive_entry_new();archive_entry_set_pathname(entry,name.c_str());archive_entry_set_filetype(entry,AE_IFREG);archive_entry_set_size(entry,static_cast<la_int64_t>(body.size()));const auto header=archive_write_header(writer.get(),entry);archive_entry_free(entry);check(header==ARCHIVE_OK&&archive_write_data(writer.get(),body.data(),body.size())==static_cast<la_ssize_t>(body.size()),"ZIP source member created only in owned fixture");}
    check(archive_write_close(writer.get())==ARCHIVE_OK,"ZIP source fixture complete");return bytes;
}
std::string cell_text(const app::FileManagementViewPage& p){std::string text;for(const auto& c:p.cells)text+=static_cast<char>(c.glyph);return text;}
